--! Screen
--#! Screenshot

hl.bind("Print", hl.dsp.exec_cmd(bin .. "/scr monitor"))
hl.bind("CTRL + SHIFT" .. " + " .. "Print", hl.dsp.exec_cmd(bin .. "/scr area"))
hl.bind("SHIFT" .. " + " .. "Print", hl.dsp.exec_cmd(bin .. "/scr area-annotate"))
hl.bind(mod .. " + CTRL" .. " + " .. "Print", hl.dsp.exec_cmd(bin .. "/scr area-annotate-delay"))
hl.bind(mod .. " + SHIFT" .. " + " .. "Print", hl.dsp.exec_cmd(bin .. "/scr extract"))

--#! Screen Record

hl.bind(mod2 .. " + " .. "Print", hl.dsp.exec_cmd(bin .. "/scr screenrec"))
hl.bind(mod2 .. " + SHIFT" .. " + " .. "Print", hl.dsp.exec_cmd(bin .. "/scr screenrec-audio"))

--#! AI

hl.bind(mod .. " + " .. mod2 .. " + SHIFT" .. " + " .. "mouse:273", hl.dsp.exec_cmd(bin .. "/primary-buffer-query.sh"))

--#! Screen modification

hl.bind(mod2 .. " + SHIFT" .. " + " .. "l", hl.dsp.exec_cmd(bin .. "/sunset"))
-- Night time screen mode
hl.bind(mod2 .. " + SHIFT" .. " + " .. "p", hl.dsp.exec_cmd("hyprctl dispatch dpms toggle"), { locked = true })
-- Toggle on/off screen
hl.bind(mod2 .. " + SHIFT + CTRL" .. " + " .. "p", hl.dsp.exec_cmd("hyprctl dispatch dpms off"), { locked = true })
-- Screen off
hl.bind(mod2 .. " + CTRL" .. " + " .. "p", hl.dsp.exec_cmd("hyprctl dispatch dpms on"), { locked = true })
-- Screen on

--! Media
--#! Local Media

hl.bind("CTRL" .. " + " .. "XF86AudioNext", hl.dsp.exec_cmd("mpc next"), { locked = true })
hl.bind("CTRL" .. " + " .. "XF86AudioPrev", hl.dsp.exec_cmd("mpc prev"), { locked = true })
