--#! Volume Control

hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("pulsemixer --change-volume +2"), { locked = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("pulsemixer --change-volume -2"), { locked = true })
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("pulsemixer --toggle-mute"), { locked = true })
hl.bind("CTRL" .. " + " .. "XF86AudioMute", hl.dsp.exec_cmd("pulsemixer --toggle-mute --id source-64"), { locked = true })

--#! Brightness Control

